const items = $input.all();
const filtered = items.filter(item => {
  const name = (item.json.name || '').toLowerCase();
  return !['.pdf','.jpg','.jpeg','.png','.gif','.mp4','.xlsx','.csv'].some(ext => name.endsWith(ext));
});
console.log('Files to process:', filtered.length, 'of', items.length);
return filtered;

const item = $input.first();
const loopItem = $('Loop Files').first().json;
const content = item.json?.data || '';

if (!content || content.length < 10) {
  console.log('Skipping empty file:', loopItem.name);
  return [];
}

// Split into paragraphs
const paragraphs = content
  .split(/\n\s*\n/)
  .map(p => p.trim())
  .filter(p => p.length > 50);

console.log('Extracted', paragraphs.length, 'paragraphs from', loopItem.name);

return paragraphs.map((para, idx) => ({
  json: {
    sourceFile: loopItem.name,
    fileId: loopItem.id,
    paragraphIndex: idx,
    paragraphText: para,
    paragraphLength: para.length
  }
}));

const allData = $input.first().json.data || [];
console.log('Starting JS deduplication on', allData.length, 'paragraphs');

function areSimilar(str1, str2, threshold = 0.9) {
  const len1 = str1.length;
  const len2 = str2.length;
  const maxLen = Math.max(len1, len2);

  if (Math.abs(len1 - len2) / maxLen > (1 - threshold)) return false;

  const words1 = new Set(str1.toLowerCase().split(/\s+/));
  const words2 = new Set(str2.toLowerCase().split(/\s+/));

  const intersection = new Set([...words1].filter(w => words2.has(w)));
  const union = new Set([...words1, ...words2]);

  const similarity = intersection.size / union.size;
  return similarity >= threshold;
}

const uniqueParagraphs = [];
const seenParagraphs = [];

for (const para of allData) {
  let isDuplicate = false;

  const compareAgainst = seenParagraphs.slice(-50);

  for (const seen of compareAgainst) {
    if (areSimilar(para.paragraphText, seen, 0.9)) {
      isDuplicate = true;
      console.log('Duplicate removed:', para.sourceFile.substring(0, 30));
      break;
    }
  }

  if (!isDuplicate) {
    uniqueParagraphs.push(para);
    seenParagraphs.push(para.paragraphText);
  }
}

console.log('Dedup done:', uniqueParagraphs.length, 'unique of', allData.length, 'total');

return uniqueParagraphs.map(p => ({ json: p }));

const items = $input.all();
if (items.length === 0) return [];

const para = items[0].json;
const text = para.paragraphText || '';

if (!text || text.length < 10) {
  return [];
}

const requestBody = {
  model: 'llama3.2',
  prompt: `Classify this L.A. Dolce Vita screenplay text. Answer ONLY: SCENE, EPISODE, or OTHER.\n\nText: ${text.substring(0, 800)}\n\nAnswer:`,
  stream: false,
  options: {
    temperature: 0.1,
    num_predict: 10
  }
};

return [{ json: { ...para, requestBody } }];

const response = $input.first().json;
const paraData = $('Prepare Classification').first().json;

let category = 'OTHER';
let episodeNum = null;

try {
  // Ollama returns response.response field
  const rawContent = response.response || '';
  const answer = String(rawContent).trim().toUpperCase();

  if (answer.includes('SCENE')) {
    category = 'SCENE';
    const epMatch = paraData.sourceFile.match(/e?(\\d{1,2})/i) || paraData.paragraphText.match(/episode\\s+(\\d{1,2})/i);
    if (epMatch) episodeNum = parseInt(epMatch[1]);
  } else if (answer.includes('EPISODE')) {
    category = 'EPISODE';
    const epMatch = paraData.sourceFile.match(/e?(\\d{1,2})/i) || paraData.paragraphText.match(/episode\\s+(\\d{1,2})/i);
    if (epMatch) episodeNum = parseInt(epMatch[1]);
  }

  // Log progress every 50 items
const loopNode = $('Loop for Classification');
const currentBatch = loopNode.context?.nodesExecuted || 0;
if (currentBatch > 0 && currentBatch % 50 === 0) {
  console.log(`💾 Progress: ${currentBatch} items processed`);
}

console.log('Classified:', category, episodeNum ? `E${episodeNum}` : '');
} catch (e) {
  console.error('Error:', e.message);
}

return [{ json: { 
  sourceFile: paraData.sourceFile,
  paragraphText: paraData.paragraphText,
  category,
  episodeNum
} }];

const allData = $input.first().json.data || [];
console.log('Grouping', allData.length, 'classified items');

const grouped = {
  episodes: {},
  scenes: [],
  other: []
};

allData.forEach(item => {
  if (item.category === 'EPISODE') {
    const ep = item.episodeNum || 0;
    const epKey = ep > 0 && ep <= 10 ? `E${ep.toString().padStart(2, '0')}` : 'Unassigned';
    if (!grouped.episodes[epKey]) grouped.episodes[epKey] = [];
    grouped.episodes[epKey].push(item);
  } else if (item.category === 'SCENE') {
    grouped.scenes.push(item);
  } else {
    grouped.other.push(item);
  }
});

console.log('✅ Grouped - Episodes:', Object.keys(grouped.episodes).length, 'Scenes:', grouped.scenes.length, 'Other:', grouped.other.length);

return [{ json: grouped }];

const grouped = $input.first().json;

function buildDoc(title, items) {
  let content = `${title}\n${'='.repeat(title.length)}\n\n`;
  items.forEach(item => {
    content += `${item.paragraphText}\n\n---\n\n`;
  });
  return content;
}

const docs = [];

// Episode doc
let episodeContent = 'L.A. Dolce Vita - Episodes\n' + '='.repeat(30) + '\n\n';
const episodeKeys = Object.keys(grouped.episodes).sort();
episodeKeys.forEach(epKey => {
  const items = grouped.episodes[epKey];
  episodeContent += `\n### ${epKey} ###\n\n`;
  items.forEach(item => {
    episodeContent += `${item.paragraphText}\n\n---\n\n`;
  });
});
docs.push({ json: { name: 'n8n_episode_results', content: episodeContent } });

// Scene doc
if (grouped.scenes.length > 0) {
  docs.push({ json: { name: 'n8n_scene_results', content: buildDoc('L.A. Dolce Vita - Scenes', grouped.scenes) } });
}

// Other doc
if (grouped.other.length > 0) {
  docs.push({ json: { name: 'n8n_other_results', content: buildDoc('L.A. Dolce Vita - Other', grouped.other) } });
}

return docs;

const dedupData = $('JS Deduplication').all();
const checkpointResults = $('Check Checkpoint Database').all();

// Get list of already processed IDs
let processedIds = [];
if (checkpointResults && checkpointResults.length > 0) {
  processedIds = checkpointResults.map(item => item.json.item_id);
}

console.log(`📋 Checkpoint: Found ${processedIds.length} already processed items`);

// Add unique IDs to all items
const withIds = dedupData.map((item, idx) => {
  const para = item.json;
  const uniqueId = `para_${idx}_${para.fileId}_${para.paragraphIndex}`;
  return { json: { ...para, uniqueId } };
});

// Filter out already processed
const processedSet = new Set(processedIds);
const remaining = withIds.filter(item => !processedSet.has(item.json.uniqueId));

console.log(`✓ Processing: ${remaining.length} remaining of ${withIds.length} total`);

return remaining;

const item = $input.first().json;

// Prepare database insert with escaped quotes for SQL
const itemDataJson = JSON.stringify(item);
const escapedItemData = itemDataJson.replace(/'/g, "''");

return [{
  json: {
    workflow_id: 'ladv_dedup',
    item_id: item.uniqueId,
    item_data: escapedItemData,
    classificationData: item
  }
}];

const countResult = $('Count Checkpoint Progress').first();
const classData = $('Continue with Data').first().json;

if (countResult && countResult.json && countResult.json[0]) {
  const total = parseInt(countResult.json[0].total);
  if (total % 50 === 0) {
    console.log(`💾 CHECKPOINT: ${total} items saved to database`);
  }
}

return [{ json: classData }];

const dbResults = $('Retrieve All Classifications').all();
console.log('✅ Retrieved', dbResults.length, 'classifications from database');

// Parse JSON from item_data column  
const allData = dbResults.map(row => {
  const itemData = row.json.item_data;
  // Data is already escaped with '', need to parse as-is
  return typeof itemData === 'string' ? JSON.parse(itemData) : itemData;
});

console.log('✅ Parsed', allData.length, 'items - grouping by category');

const grouped = {
  episodes: {},
  scenes: [],
  other: []
};

allData.forEach(item => {
  if (item.category === 'EPISODE') {
    const ep = item.episodeNum || 0;
    const epKey = ep > 0 && ep <= 10 ? `E${ep.toString().padStart(2, '0')}` : 'Unassigned';
    if (!grouped.episodes[epKey]) grouped.episodes[epKey] = [];
    grouped.episodes[epKey].push(item);
  } else if (item.category === 'SCENE') {
    grouped.scenes.push(item);
  } else {
    grouped.other.push(item);
  }
});

console.log('✅ Episodes:', Object.keys(grouped.episodes).length, 'Scenes:', grouped.scenes.length, 'Other:', grouped.other.length);

return [{ json: grouped }];

