const timestamp = new Date().toISOString();
const timestampFormatted = timestamp.replace('T', ' ').split('.')[0];

const workflowName = $workflow.name || 'LADV Dedup Ollama';
const workflowId = $workflow.id || 'N/A';
const executionId = $execution.id || 'N/A';

const errorData = $('ErrorTrigger-901').first().json;
const errorNode = errorData.node?.name || 'Unknown Node';
const errorMessage = errorData.error?.message || 'No error message available';
const errorStack = errorData.error?.stack || 'No stack trace available';

let checkpointData = 'No checkpoint data available';
try {
  const checkpointNode = $('ReadCheckpoint-902').first();
  if (checkpointNode && checkpointNode.binary && checkpointNode.binary.data) {
    const buffer = Buffer.from(checkpointNode.binary.data.data);
    checkpointData = buffer.toString('utf8');
  }
} catch (e) {
  checkpointData = `Checkpoint read error: ${e.message}`;
}

const executionData = JSON.stringify(errorData, null, 2);

const emailSubject = `🚨 n8n Workflow Failed: ${workflowName} - ${timestampFormatted}`;

const emailBody = `
═══════════════════════════════════════════════════════════
n8n WORKFLOW EXECUTION FAILURE REPORT
═══════════════════════════════════════════════════════════

Workflow Name: ${workflowName}
Workflow ID: ${workflowId}
Execution ID: ${executionId}
Failure Time: ${timestampFormatted}

───────────────────────────────────────────────────────────
FAILED NODE
───────────────────────────────────────────────────────────
${errorNode}

───────────────────────────────────────────────────────────
ERROR MESSAGE
───────────────────────────────────────────────────────────
${errorMessage}

───────────────────────────────────────────────────────────
STACK TRACE
───────────────────────────────────────────────────────────
${errorStack}

───────────────────────────────────────────────────────────
CHECKPOINT DATA (PostgreSQL)
───────────────────────────────────────────────────────────
${checkpointData}

───────────────────────────────────────────────────────────
FULL EXECUTION DATA
───────────────────────────────────────────────────────────
${executionData}

═══════════════════════════════════════════════════════════
DEBUGGING INSTRUCTIONS
═══════════════════════════════════════════════════════════

1. Copy this ENTIRE email (Ctrl+A, Ctrl+C)
2. Send it to Claude Code with message: "analyze and fix"
3. Claude will:
   - Identify the root cause
   - Provide specific code fixes
   - Update the workflow JSON
   - Handle checkpoint recovery if needed

4. Workflow uses PostgreSQL checkpointing:
   - Query: SELECT * FROM workflow_checkpoints WHERE workflow_id = 'ladv_dedup'
   - Resume from last successful item after fixes applied

═══════════════════════════════════════════════════════════
`;

return [{
  json: {
    subject: emailSubject,
    body: emailBody,
    timestamp: timestamp,
    workflowName: workflowName,
    executionId: executionId
  }
}];

const timestamp = new Date().toISOString();
console.log(`[${timestamp}] Error notification email sent successfully`);
console.log(`Execution ID: ${$('FormatErrorLog-903').first().json.executionId}`);

return [{
  json: {
    emailSent: true,
    timestamp: timestamp
  }
}];
